\begin{equation*}
\cohog{*}{\cB_{\cQ}^{\Herm}((\Fr y)^{\sh})}\xr{\t_{y}}\cohog{*}{\cB_{\cQ}^{\Herm}(\Fr (y^{\sh}))} \xr{\Fr^{*}}\cohog{*}{\cB_{\cQ}^{\Herm}(y^{\sh})}
