\item An isomorphism $\varphi \co \Cal{F}_r \cong \ft \Cal{F}_0$ compatible with the Hermitian structure.
\end{enumerate}
\end{defn}


\begin{lemma}
\source{higher-siegel-weil-unitary-nonsingular-terms}
