\begin{equation}\label{eq: comparison 1}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\wt{E}_{a}(m(\cE),s,\Phi) =  \Tr(\Frob,\cK_{d}^{\Eis}(q^{-2s})_{\cQ}).
